<?php $pageTitle='Users and roles';$currentId=(int)(app()->auth()->user()['id']??0); ?>
<div class="rbac-page">
<section class="page-heading"><div><p class="eyebrow">Access governance</p><h1>Users and role permissions</h1><p>Create accountable staff access and review what each operational role can manage.</p></div></section>
