<section class="rbac-layout"><form class="panel rbac-create" method="post" action="<?= e(url('users')) ?>"><?= csrf_field() ?><div><p class="eyebrow">New staff access</p><h2>Create user account</h2><p>Use an individual account for every authorized staff member.</p></div><label>Full name<input name="name" required placeholder="Staff member name"></label><label>Username<input name="username" required minlength="3" pattern="[A-Za-z0-9._-]+" autocomplete="off" placeholder="exam.coordinator"></label><label>University email<input name="email" type="email" placeholder="name@gbu.ac.in"></label><label>Role<select name="role_id" required><option value="">Select responsibility</option><?php foreach($roles as $role):?><option value="<?= (int)$role['id'] ?>"><?= e($role['name']) ?></option><?php endforeach;?></select></label><label>Temporary password<input name="password" type="password" minlength="12" autocomplete="new-password" required placeholder="At least 12 characters"></label><input type="hidden" name="status" value="active"><button class="primary-button" type="submit">Create secure account</button></form>
<section class="rbac-roles" aria-labelledby="role-matrix-title"><div class="rbac-section-heading"><div><p class="eyebrow">Permission matrix</p><h2 id="role-matrix-title">Operational responsibilities</h2></div><span><?= count($roles) ?> defined roles</span></div><div class="rbac-role-list"><?php foreach($roles as $role):?><article><header><strong><?= e($role['name']) ?></strong><code><?= e($role['code']) ?></code></header><p><?= e($role['description']) ?></p><div><?php foreach($role['permissions'] as $permission):?><span><?= e($permissionLabels[$permission]??$permission) ?></span><?php endforeach;?></div></article><?php endforeach;?></div></section></section>
<section class="panel rbac-users"><div class="rbac-section-heading"><div><p class="eyebrow">Account register</p><h2><?= count($users) ?> authorized users</h2></div><span>Changes are written to the audit log</span></div><div class="rbac-user-list"><?php foreach($users as $user):?><form method="post" action="<?= e(url('users/'.$user['id'])) ?>" class="rbac-user"><?= csrf_field() ?><div class="rbac-user-identity"><span><?= e(strtoupper(substr($user['name'],0,1))) ?></span><div><strong><?= e($user['name']) ?><?= (int)$user['id']===$currentId?' (You)':'' ?></strong><small>@<?= e($user['username']) ?> · <?= e($user['email']?:'No email recorded') ?></small></div></div><label><span>Name</span><input name="name" value="<?= e($user['name']) ?>" required></label><label><span>Username</span><input name="username" value="<?= e($user['username']) ?>" required></label><label><span>Email</span><input name="email" type="email" value="<?= e($user['email']??'') ?>"></label><label><span>Role</span><select name="role_id" <?= (int)$user['id']===$currentId?'disabled':'' ?>><?php foreach($roles as $role):?><option value="<?= (int)$role['id'] ?>" <?= (int)$role['id']===(int)$user['role_id']?'selected':'' ?>><?= e($role['name']) ?></option><?php endforeach;?></select><?php if((int)$user['id']===$currentId):?><input type="hidden" name="role_id" value="<?= (int)$user['role_id'] ?>"><?php endif;?></label><label><span>Status</span><select name="status" <?= (int)$user['id']===$currentId?'disabled':'' ?>><option value="active" <?= $user['status']==='active'?'selected':'' ?>>Active</option><option value="inactive" <?= $user['status']==='inactive'?'selected':'' ?>>Inactive</option><option value="locked" <?= $user['status']==='locked'?'selected':'' ?>>Locked</option></select><?php if((int)$user['id']===$currentId):?><input type="hidden" name="status" value="active"><?php endif;?></label><label><span>New password</span><input name="password" type="password" minlength="12" autocomplete="new-password" placeholder="Leave unchanged"></label><div class="rbac-user-meta"><span class="status-label <?= e($user['status']) ?>"><?= e(ucfirst($user['status'])) ?></span><small><?= $user['last_login_at']?'Last sign-in '.e(date('d M Y, H:i',strtotime($user['last_login_at']))):'Never signed in' ?></small><button class="secondary-button" type="submit">Save access</button></div></form><?php endforeach;?></div></section>
